def delivery_fee(total: int) -> int:
    if type(total) is not int or total < 0:
        raise ValueError("訂單金額必須是非負整數")
    if total >= 1000:
        return 0
    return 60

import pytest
from rules import delivery_fee

@pytest.mark.parametrize("amount, expected", [(0, 60), (999, 60), (1000, 0), (1001, 0)])
def test_delivery_fee(amount, expected):
    assert delivery_fee(amount) == expected

@pytest.mark.parametrize("bad", [-1, 1.5, "1000", True])
def test_invalid_amount(bad):
    with pytest.raises(ValueError):
        delivery_fee(bad)

import pytest
from rules import validate, export_report

GOOD = {"application_id": "SYN-001", "applicant_code": "DEMO-A", "document_type": "合成申請表"}

@pytest.mark.parametrize("field", ["application_id", "applicant_code", "document_type"])
@pytest.mark.parametrize("bad", ["", "   ", "\t\n", None, 42, "x" * 81])
def test_invalid_field(field, bad):
    record = {**GOOD, field: bad}
    assert validate(record)
    with pytest.raises(ValueError):
        export_report(record)

import json
import pytest
from rules import validate, export_report

GOOD = {"application_id": "SYN-001", "applicant_code": "DEMO-A", "document_type": "合成申請表"}


@pytest.mark.parametrize("field", tuple(GOOD))
@pytest.mark.parametrize("bad", ["", "   ", "\t\n", None, 42, "x" * 81])
def test_each_invalid_field_is_rejected(field, bad):
    record = {**GOOD, field: bad}
    assert validate(record)
    with pytest.raises(ValueError):
        export_report(record)


@pytest.mark.parametrize("size,accepted", [(80, True), (81, False)])
def test_length_boundary(size, accepted):
    record = {**GOOD, "application_id": "x" * size}
    assert (validate(record) == []) is accepted


def test_valid_export_uses_only_allowed_fields():
    record = {**GOOD, "application_id": " SYN-001 ", "debug_note": "not-exported"}
    result = json.loads(export_report(record))
    assert result["status"] == "complete"
    assert result["data"] == GOOD
    assert "debug_note" not in result["data"]
    assert record["application_id"] == " SYN-001 "


def test_missing_key_is_rejected():
    record = GOOD.copy()
    del record["document_type"]
    with pytest.raises(ValueError):
        export_report(record)

